  flockData() {
    if (this._F) return this._F;
    const q = (p0, c, p2, t) => {
      const x = (1 - t) * (1 - t) * p0[0] + 2 * (1 - t) * t * c[0] + t * t * p2[0];
      const y = (1 - t) * (1 - t) * p0[1] + 2 * (1 - t) * t * c[1] + t * t * p2[1];
      const dx = 2 * (1 - t) * (c[0] - p0[0]) + 2 * t * (p2[0] - c[0]);
      const dy = 2 * (1 - t) * (c[1] - p0[1]) + 2 * t * (p2[1] - c[1]);
      return { x: x, y: y, a: Math.atan2(dy, dx) * 180 / Math.PI };
    };
    const rnd = (n) => { const v = Math.sin(n * 12.9898 + 78.233) * 43758.5453; return v - Math.floor(v); };
    const cols = ['c-mus', 'c-red', 'c-sky', 'c-ink'];
    const out = [];
    const n = 11;
    for (let i = 0; i < n; i++) {
      const t = (i + 0.5) / n;
      const top = q([40, 210], [500, -60], [960, 210], t);
      const bot = q([960, 210], [500, 480], [40, 210], t);
      [top, bot].forEach((pt, k) => {
        const idx = i * 2 + k;
        out.push({ x: Math.round(pt.x / 10 * 100) / 100, y: Math.round(pt.y / 4.2 * 100) / 100, sx: Math.round((rnd(idx) - 0.5) * 1100), sy: Math.round((rnd(idx + 40) - 0.5) * 700 - 120), r0: Math.round((rnd(idx + 80) - 0.5) * 140), rt: Math.round(k === 0 ? pt.a : pt.a + 180) % 360, cls: cols[idx % 4] });
      });
    }
    this._F = out;
    return out;
  }

